import type {
  CreateNoteInput,
  Note,
  UpdateNoteInput,
} from "@/types/note";

const API_BASE = import.meta.env.VITE_API_URL ?? "";

interface ApiSuccessResponse<T> {
  success: true;
  data: T;
}

interface ApiErrorResponse {
  success: false;
  message: string;
}

export class ApiRequestError extends Error {
  constructor(
    message: string,
    public readonly status: number,
  ) {
    super(message);
    this.name = "ApiRequestError";
  }
}

async function request<T>(
  path: string,
  init?: RequestInit,
): Promise<T> {
  const response = await fetch(`${API_BASE}${path}`, {
    headers: {
      "Content-Type": "application/json",
      ...init?.headers,
    },
    ...init,
  });

  const body = (await response.json()) as ApiSuccessResponse<T> | ApiErrorResponse;

  if (!response.ok || !body.success) {
    const message = body.success
      ? `Request failed with status ${response.status}`
      : body.message;
    throw new ApiRequestError(message, response.status);
  }

  return body.data;
}

export const notesApi = {
  list(search?: string) {
    const params = search ? `?search=${encodeURIComponent(search)}` : "";
    return request<Note[]>(`/notes${params}`);
  },

  get(id: number) {
    return request<Note>(`/notes/${id}`);
  },

  create(input: CreateNoteInput) {
    return request<Note>("/notes", {
      method: "POST",
      body: JSON.stringify(input),
    });
  },

  update(id: number, input: UpdateNoteInput) {
    return request<Note>(`/notes/${id}`, {
      method: "PUT",
      body: JSON.stringify(input),
    });
  },

  delete(id: number) {
    return request<null>(`/notes/${id}`, {
      method: "DELETE",
    });
  },
};

import ReactMarkdown from "react-markdown";
import remarkGfm from "remark-gfm";

interface MarkdownPreviewProps {
  content: string;
}

export function MarkdownPreview({ content }: MarkdownPreviewProps) {
  return (
    <div className="prose prose-sm max-w-none dark:prose-invert">
      <ReactMarkdown remarkPlugins={[remarkGfm]}>
        {content || "*Nothing to preview yet.*"}
      </ReactMarkdown>
    </div>
  );
}

import { AlertCircle, Eye, Loader2, Pencil, Trash2 } from "lucide-react";
import { useEffect, useState } from "react";
import { toast } from "sonner";
import { MarkdownPreview } from "@/components/notes/markdown-preview";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { useAutosave } from "@/hooks/use-autosave";
import { useDeleteNote, useUpdateNote } from "@/hooks/use-notes";
import { formatDate } from "@/lib/utils";
import type { Note } from "@/types/note";

interface NoteEditorProps {
  note: Note;
  onDeleted: () => void;
}

type ViewMode = "edit" | "preview";

export function NoteEditor({ note, onDeleted }: NoteEditorProps) {
  const [title, setTitle] = useState(note.title);
  const [content, setContent] = useState(note.content);
  const [viewMode, setViewMode] = useState<ViewMode>("edit");
  const updateNote = useUpdateNote();
  const deleteNote = useDeleteNote();

  useEffect(() => {
    setTitle(note.title);
    setContent(note.content);
  }, [note.id, note.title, note.content]);

  const { isSaving, lastSavedAt, error } = useAutosave({
    value: { title, content },
    enabled: !updateNote.isPending,
    onSave: async (value) => {
      await updateNote.mutateAsync({
        id: note.id,
        input: value,
      });
    },
  });

  useEffect(() => {
    if (error) {
      toast.error(error);
    }
  }, [error]);

  async function handleDelete() {
    try {
      await deleteNote.mutateAsync(note.id);
      toast.success("Note deleted");
      onDeleted();
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Failed to delete note",
      );
    }
  }

  return (
    <div className="flex h-full flex-col">
      <div className="flex flex-wrap items-center gap-2 border-b px-4 py-3">
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <Input
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            placeholder="Note title"
            className="border-none px-0 text-lg font-semibold shadow-none focus-visible:ring-0"
          />
        </div>
        <div className="flex items-center gap-2">
          <Button
            variant={viewMode === "edit" ? "secondary" : "outline"}
            size="sm"
            onClick={() => setViewMode("edit")}
          >
            <Pencil className="h-4 w-4" />
            Edit
          </Button>
          <Button
            variant={viewMode === "preview" ? "secondary" : "outline"}
            size="sm"
            onClick={() => setViewMode("preview")}
          >
            <Eye className="h-4 w-4" />
            Preview
          </Button>
          <Button
            variant="destructive"
            size="sm"
            onClick={() => void handleDelete()}
            disabled={deleteNote.isPending}
          >
            {deleteNote.isPending ? (
              <Loader2 className="h-4 w-4 animate-spin" />
            ) : (
              <Trash2 className="h-4 w-4" />
            )}
            Delete
          </Button>
        </div>
      </div>

      <div className="flex items-center gap-2 border-b px-4 py-2 text-xs text-muted-foreground">
        {isSaving || updateNote.isPending ? (
          <>
            <Loader2 className="h-3 w-3 animate-spin" />
            Saving…
          </>
        ) : lastSavedAt ? (
          <>Saved {formatDate(lastSavedAt.toISOString())}</>
        ) : (
          <>Updated {formatDate(note.updatedAt)}</>
        )}
        {error && (
          <span className="inline-flex items-center gap-1 text-destructive">
            <AlertCircle className="h-3 w-3" />
            Save failed
          </span>
        )}
      </div>

      <div className="flex-1 overflow-auto p-4">
        {viewMode === "edit" ? (
          <Textarea
            value={content}
            onChange={(event) => setContent(event.target.value)}
            placeholder="Write your note in Markdown…"
            className="min-h-[calc(100vh-220px)] resize-none border-none p-0 shadow-none focus-visible:ring-0"
          />
        ) : (
          <MarkdownPreview content={content} />
        )}
      </div>
    </div>
  );
}

import { AlertCircle, FileText } from "lucide-react";
import { Button } from "@/components/ui/button";
import { cn, formatDate, getPreviewText } from "@/lib/utils";
import type { Note } from "@/types/note";

interface NoteListProps {
  notes: Note[];
  selectedId: number | null;
  onSelect: (id: number) => void;
  isLoading: boolean;
  isError: boolean;
  onRetry: () => void;
}

export function NoteList({
  notes,
  selectedId,
  onSelect,
  isLoading,
  isError,
  onRetry,
}: NoteListProps) {
  if (isLoading) {
    return (
      <div className="space-y-3 p-4">
        {Array.from({ length: 5 }).map((_, index) => (
          <div key={index} className="space-y-2 rounded-lg border p-3">
            <div className="h-4 w-2/3 animate-pulse rounded bg-muted" />
            <div className="h-3 w-full animate-pulse rounded bg-muted" />
          </div>
        ))}
      </div>
    );
  }

  if (isError) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center">
        <AlertCircle className="h-8 w-8 text-destructive" />
        <p className="text-sm text-muted-foreground">
          Failed to load notes. Please try again.
        </p>
        <Button variant="outline" size="sm" onClick={onRetry}>
          Retry
        </Button>
      </div>
    );
  }

  if (notes.length === 0) {
    return (
      <div className="flex h-full flex-col items-center justify-center gap-2 p-6 text-center text-muted-foreground">
        <FileText className="h-8 w-8" />
        <p className="text-sm">No notes yet. Create your first note.</p>
      </div>
    );
  }

  return (
    <div className="divide-y">
      {notes.map((note) => (
        <button
          key={note.id}
          type="button"
          onClick={() => onSelect(note.id)}
          className={cn(
            "w-full px-4 py-3 text-left transition-colors hover:bg-accent",
            selectedId === note.id && "bg-accent",
          )}
        >
          <p className="truncate font-medium">
            {note.title.trim() || "Untitled"}
          </p>
          <p className="mt-1 truncate text-sm text-muted-foreground">
            {getPreviewText(note.content)}
          </p>
          <p className="mt-2 text-xs text-muted-foreground">
            {formatDate(note.updatedAt)}
          </p>
        </button>
      ))}
    </div>
  );
}

import { Loader2, Plus, Search } from "lucide-react";
import { useMemo, useState } from "react";
import { toast } from "sonner";
import { NoteEditor } from "@/components/notes/note-editor";
import { NoteList } from "@/components/notes/note-list";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";
import { useCreateNote, useNote, useNotes } from "@/hooks/use-notes";

export function NotesApp() {
  const [search, setSearch] = useState("");
  const [selectedId, setSelectedId] = useState<number | null>(null);
  const [sidebarOpen, setSidebarOpen] = useState(true);

  const notesQuery = useNotes(search);
  const selectedNoteQuery = useNote(selectedId);
  const createNote = useCreateNote();

  const notes = useMemo(() => notesQuery.data ?? [], [notesQuery.data]);

  async function handleCreateNote() {
    try {
      const note = await createNote.mutateAsync({
        title: "Untitled",
        content: "",
      });
      setSelectedId(note.id);
      setSidebarOpen(false);
      toast.success("Note created");
    } catch (err) {
      toast.error(
        err instanceof Error ? err.message : "Failed to create note",
      );
    }
  }

  return (
    <div className="flex h-screen flex-col bg-background">
      <header className="flex items-center justify-between border-b px-4 py-3">
        <div>
          <h1 className="text-lg font-semibold">Simple Note</h1>
          <p className="text-sm text-muted-foreground">
            Markdown notes with autosave
          </p>
        </div>
        <Button onClick={() => void handleCreateNote()} disabled={createNote.isPending}>
          {createNote.isPending ? (
            <Loader2 className="h-4 w-4 animate-spin" />
          ) : (
            <Plus className="h-4 w-4" />
          )}
          New note
        </Button>
      </header>

      <div className="flex min-h-0 flex-1">
        <aside
          className={`flex w-full flex-col border-r md:w-80 lg:w-96 ${
            sidebarOpen ? "flex" : "hidden md:flex"
          }`}
        >
          <div className="p-3">
            <div className="relative">
              <Search className="absolute top-2.5 left-3 h-4 w-4 text-muted-foreground" />
              <Input
                value={search}
                onChange={(event) => setSearch(event.target.value)}
                placeholder="Search notes…"
                className="pl-9"
              />
            </div>
          </div>
          <Separator />
          <ScrollArea className="flex-1">
            <NoteList
              notes={notes}
              selectedId={selectedId}
              onSelect={(id) => {
                setSelectedId(id);
                setSidebarOpen(false);
              }}
              isLoading={notesQuery.isLoading}
              isError={notesQuery.isError}
              onRetry={() => void notesQuery.refetch()}
            />
          </ScrollArea>
        </aside>

        <main className="min-w-0 flex-1">
          {selectedId === null ? (
            <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center text-muted-foreground">
              <p>Select a note or create a new one to get started.</p>
              <Button variant="outline" onClick={() => void handleCreateNote()}>
                Create note
              </Button>
            </div>
          ) : selectedNoteQuery.isLoading ? (
            <div className="flex h-full items-center justify-center">
              <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            </div>
          ) : selectedNoteQuery.isError || !selectedNoteQuery.data ? (
            <div className="flex h-full flex-col items-center justify-center gap-3 p-6 text-center">
              <p className="text-muted-foreground">Failed to load this note.</p>
              <Button
                variant="outline"
                onClick={() => void selectedNoteQuery.refetch()}
              >
                Retry
              </Button>
            </div>
          ) : (
            <div className="flex h-full flex-col">
              <div className="border-b px-4 py-2 md:hidden">
                <Button
                  variant="ghost"
                  size="sm"
                  onClick={() => setSidebarOpen(true)}
                >
                  Back to notes
                </Button>
              </div>
              <NoteEditor
                note={selectedNoteQuery.data}
                onDeleted={() => setSelectedId(null)}
              />
            </div>
          )}
        </main>
      </div>
    </div>
  );
}

